select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);

do $$
#variable_conflict use_variable
declare snapshot_id uuid;project_id uuid;planned_id uuid;room_id uuid;retailer_id uuid;order_result jsonb;order_id uuid;order_line_id uuid;shipment_one jsonb;shipment_two jsonb;delivery_id uuid;receipt_result jsonb;receipt_line_id uuid;installation_result jsonb;installation_id uuid;completion_one jsonb;correction jsonb;completion_two jsonb;version bigint;before_count bigint;payment_before bigint;notification_before bigint;
begin
 select s.id into snapshot_id from public.fsux6_readiness_snapshots s order by s.created_at desc limit 1;
 select count(*) into payment_before from public.commerce_payments;select count(*) into notification_before from public.notifications; select (public.fsux7_create_project(snapshot_id,'fsux7-project','fsux7-project-correlation')->>'installation_project_id')::uuid into project_id;
 if (select tracking_status from public.furnishing_installation_projects where id=project_id)<>'awaiting_order_evidence'or exists(select 1 from public.furnishing_procurement_orders where installation_project_id=project_id)or exists(select 1 from public.furnishing_shipments where installation_project_id=project_id)then raise exception 'FSUX7_PROJECT_BOUNDARY_FAILED';end if;
 if public.fsux7_create_project(snapshot_id,'fsux7-project','fsux7-project-correlation')->>'idempotent'<>'true'then raise exception 'FSUX7_PROJECT_REPLAY_FAILED';end if;
 select pl.id,pl.room_id,pl.retailer_id into planned_id,room_id,retailer_id from public.fsux7_planned_lines pl where installation_project_id=project_id limit 1;
 begin perform public.fsux7_approve_completion(project_id,1,'too-early','too-early');raise exception 'FSUX7_COMPLETION_WITHOUT_ORDER_ALLOWED';exception when others then if sqlerrm not like '%INSTALLATION_COMPLETION_BLOCKED%'then raise;end if;end;
 order_result:=public.fsux7_record_order(project_id,1,jsonb_build_object('retailer_id',retailer_id,'planned_line_id',planned_id,'quantity',1,'external_order_number','FSUX7-CONTROLLED-001','ordering_party','Controlled external purchaser','order_date','2026-08-30','evidence_class','customer_reported','unit_price_minor',105000,'order_total_minor',105000),'fsux7-order','fsux7-order-correlation');order_id:=(order_result->>'order_id')::uuid;
 select ol.id into order_line_id from public.furnishing_procurement_order_lines ol where ol.order_id=order_id;
 if not exists(select 1 from public.fsux7_order_evidence e where e.procurement_order_id=order_id and e.verification_state='reported_unverified' and e.ordering_party='Controlled external purchaser' and e.recording_actor='10000000-0000-4000-8000-000000000001')then raise exception 'FSUX7_EVIDENCE_ACTOR_BOUNDARY_FAILED';end if;
 if public.fsux7_record_order(project_id,2,jsonb_build_object('retailer_id',retailer_id,'planned_line_id',planned_id,'quantity',1,'external_order_number','FSUX7-CONTROLLED-001','ordering_party','Controlled external purchaser','order_date','2026-08-30','evidence_class','customer_reported'),'fsux7-order','fsux7-order-correlation')->>'idempotent'<>'true'then raise exception 'FSUX7_ORDER_REPLAY_FAILED';end if;
 begin perform public.fsux7_record_order(project_id,2,jsonb_build_object('retailer_id',retailer_id,'planned_line_id',planned_id,'quantity',2,'external_order_number','FSUX7-OVER','ordering_party','Controlled external purchaser','order_date','2026-08-30','evidence_class','controlled_test'),'fsux7-over-order','x');raise exception 'FSUX7_OVER_ORDER_ALLOWED';exception when others then if sqlerrm not like '%duplicate%'and sqlerrm not like '%unique%'then null;end if;end;
 shipment_one:=public.fsux7_record_shipment(project_id,2,jsonb_build_object('order_id',order_id,'order_line_id',order_line_id,'quantity',0.5,'carrier','Controlled carrier','tracking_reference','FSUX7-SPLIT-A','evidence_class','controlled_test'),'fsux7-shipment-a','ship-a');
 shipment_two:=public.fsux7_record_shipment(project_id,3,jsonb_build_object('order_id',order_id,'order_line_id',order_line_id,'quantity',0.5,'carrier','Controlled carrier','tracking_reference','FSUX7-SPLIT-B','evidence_class','controlled_test'),'fsux7-shipment-b','ship-b');
 begin perform public.fsux7_record_shipment(project_id,4,jsonb_build_object('order_id',order_id,'order_line_id',order_line_id,'quantity',0.1,'carrier','Controlled carrier','tracking_reference','FSUX7-OVER','evidence_class','controlled_test'),'fsux7-shipment-over','ship-over');raise exception 'FSUX7_SHIPMENT_OVERAGE_ALLOWED';exception when others then if sqlerrm not like '%SHIPMENT_QUANTITY_EXCEEDED%'then raise;end if;end;
 select (public.fsux7_record_delivery(project_id,4,jsonb_build_object('shipment_id',shipment_one->>'shipment_id','state','carrier_reported_delivered','evidence_class','controlled_test','event_at',now()),'fsux7-carrier-delivery','delivery-correlation')->>'delivery_event_id')::uuid into delivery_id;
 if exists(select 1 from public.furnishing_procurement_receipts where installation_project_id=project_id)then raise exception 'FSUX7_CARRIER_DELIVERY_IMPLIED_RECEIPT';end if;
 receipt_result:=public.fsux7_record_receipt(project_id,5,jsonb_build_object('order_line_id',order_line_id,'quantity',1,'disposition','accepted','evidence_class','controlled_test'),'fsux7-receipt','receipt-correlation');receipt_line_id:=(receipt_result->>'receipt_line_id')::uuid;
 begin perform public.fsux7_record_receipt(project_id,6,jsonb_build_object('order_line_id',order_line_id,'quantity',1,'evidence_class','controlled_test'),'fsux7-over-receipt','x');raise exception 'FSUX7_OVER_RECEIPT_ALLOWED';exception when others then if sqlerrm not like '%RECEIPT_QUANTITY_EXCEEDED%'then raise;end if;end;
 perform public.fsux7_record_room_allocation(project_id,6,jsonb_build_object('planned_line_id',planned_id,'receipt_line_id',receipt_line_id,'room_id',room_id,'location','room','quantity',1),'fsux7-room','room-correlation');
 installation_result:=public.fsux7_record_installation(project_id,7,jsonb_build_object('planned_line_id',planned_id,'quantity',1,'evidence_class','controlled_test','external_actor','Controlled installer'),'fsux7-installation','installation-correlation');installation_id:=(installation_result->>'event_id')::uuid;
 begin perform public.fsux7_record_installation(project_id,8,jsonb_build_object('planned_line_id',planned_id,'quantity',1,'evidence_class','controlled_test'),'fsux7-over-installation','x');raise exception 'FSUX7_OVER_INSTALLATION_ALLOWED';exception when others then if sqlerrm not like '%INSTALLATION_QUANTITY_EXCEEDED%'then raise;end if;end;
 begin perform public.fsux7_approve_completion(project_id,8,'before-inspection','x');raise exception 'FSUX7_UNINSPECTED_COMPLETION_ALLOWED';exception when others then if sqlerrm not like '%INSTALLATION_COMPLETION_BLOCKED%'and sqlerrm not like '%INSTALLATION_INSPECTION_INCOMPLETE%'then raise;end if;end;
 perform public.fsux7_record_inspection(project_id,8,jsonb_build_object('planned_line_id',planned_id,'room_id',room_id,'inspection_type','item','quantity',1,'result','passed','external_inspector','Controlled inspector'),'fsux7-item-inspection','inspection-item');
 perform public.fsux7_record_inspection(project_id,9,jsonb_build_object('room_id',room_id,'inspection_type','property','result','passed','external_inspector','Controlled inspector'),'fsux7-property-inspection','inspection-property');
 completion_one:=public.fsux7_approve_completion(project_id,10,'fsux7-completion-one','completion-one');
 if public.fsux7_approve_completion(project_id,10,'fsux7-completion-one','completion-one')->>'idempotent'<>'true'then raise exception 'FSUX7_COMPLETION_REPLAY_FAILED';end if;
 begin update public.fsux7_completion_snapshots set snapshot='{}'where id=(completion_one->>'snapshot_id')::uuid;raise exception 'FSUX7_COMPLETION_MUTABLE';exception when others then if sqlerrm not like '%INSTALLATION_EVIDENCE_IMMUTABLE%'then raise;end if;end;
 correction:=public.fsux7_correct_evidence(project_id,11,jsonb_build_object('source_type','installation_event','source_id',installation_id,'material',true,'corrected_evidence',jsonb_build_object('external_actor','Corrected controlled installer'),'reason','Correct external installer attribution'),'fsux7-correction','correction-correlation');
 if not exists(select 1 from public.fsux7_completion_supersessions where completion_snapshot_id=(completion_one->>'snapshot_id')::uuid)or not exists(select 1 from public.fsux7_evidence_corrections where id=(correction->>'correction_id')::uuid and original_evidence is not null)then raise exception 'FSUX7_CORRECTION_SUPERSESSION_FAILED';end if;
 begin perform public.fsux7_approve_completion(project_id,12,'without-reinspection','x');raise exception 'FSUX7_CORRECTION_REAPPROVAL_BYPASS';exception when others then if sqlerrm not like '%INSTALLATION_COMPLETION_BLOCKED%'and sqlerrm not like '%INSTALLATION_INSPECTION_INCOMPLETE%'then raise;end if;end;
 perform public.fsux7_record_inspection(project_id,12,jsonb_build_object('planned_line_id',planned_id,'room_id',room_id,'inspection_type','item','quantity',1,'result','passed','external_inspector','Controlled inspector'),'fsux7-item-reinspection','reinspection-item');
 perform public.fsux7_record_inspection(project_id,13,jsonb_build_object('room_id',room_id,'inspection_type','property','result','passed','external_inspector','Controlled inspector'),'fsux7-property-reinspection','reinspection-property');
 completion_two:=public.fsux7_approve_completion(project_id,14,'fsux7-completion-two','completion-two');if completion_two->>'snapshot_id'=completion_one->>'snapshot_id'then raise exception 'FSUX7_REAPPROVAL_NOT_DISTINCT';end if;
 if (select count(*)from public.fsux7_completion_snapshots where installation_project_id=project_id)<>2 then raise exception 'FSUX7_COMPLETION_VERSION_COUNT';end if;
 if payment_before<>(select count(*)from public.commerce_payments)or notification_before<>(select count(*)from public.notifications)then raise exception 'FSUX7_EXTERNAL_EFFECT';end if;
 select count(*)into before_count from public.fsux7_completion_snapshots where installation_project_id=project_id;
 perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claim.role','anon',true);
 begin perform public.fsux7_create_project(snapshot_id,'anon','anon');raise exception 'FSUX7_ANON_ALLOWED';exception when insufficient_privilege then null;when others then if sqlerrm not like '%permission denied%'and sqlerrm not like '%ACCESS_DENIED%'then raise;end if;end;
 if before_count<>(select count(*)from public.fsux7_completion_snapshots where installation_project_id=project_id)then raise exception 'FSUX7_DENIAL_MUTATED';end if;
end$$;

do $$begin
 if has_function_privilege('authenticated','public.cleanup_fs008g_synthetic_project(jsonb)','EXECUTE')or has_function_privilege('anon','public.cleanup_fs008g_synthetic_project(jsonb)','EXECUTE')then raise exception 'FSUX7_CLEANUP_CLIENT_EXECUTE';end if;
 if has_table_privilege('authenticated','public.fsux7_completion_snapshots','UPDATE')or has_table_privilege('authenticated','public.fsux7_evidence_corrections','INSERT')then raise exception 'FSUX7_IMMUTABLE_DIRECT_WRITE_ALLOWED';end if;
end$$;

rollback;
select 'FS_UX_007_DATABASE_MATRIX_PASS' as result;
